import{_ as a,a as t,o as n,ai as i}from"./chunks/framework.BbOtTPsL.js";const l=JSON.parse('{"title":"Campaigns","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/marketing/communications/campaigns/index.md","filePath":"api/graphql-api/admin/marketing/communications/campaigns/index.md","lastUpdated":1782473079000}'),o={name:"api/graphql-api/admin/marketing/communications/campaigns/index.md"};function r(d,e,s,c,m,p){return n(),t("div",null,e[0]||(e[0]=[i('<h1 id="campaigns" tabindex="-1">Campaigns <a class="header-anchor" href="#campaigns" aria-label="Permalink to &quot;Campaigns&quot;">​</a></h1><p>A <strong>campaign</strong> pairs an email template with a customer group (and an optional event) and sends that email to the group&#39;s subscribed members. It mirrors the admin <strong>Marketing → Communications → Campaigns</strong> screen.</p><h2 id="how-a-campaign-works" tabindex="-1">How a campaign works <a class="header-anchor" href="#how-a-campaign-works" aria-label="Permalink to &quot;How a campaign works&quot;">​</a></h2><p>A campaign brings together four pieces of marketing data and a subject line:</p><ul><li><strong>Email template</strong> (<code>marketingTemplate</code>) — the HTML body that gets sent. Set up under <strong>Marketing → Communications → Email Templates</strong>. Linked on create / update by its id (<code>marketingTemplateId</code>).</li><li><strong>Customer group</strong> (<code>customerGroup</code>) — who receives it. The send goes to the subscribed members of this group; for a guest group it goes to the guest newsletter subscribers. Linked by id (<code>customerGroupId</code>).</li><li><strong>Channel</strong> (<code>channel</code>) — the storefront channel the campaign belongs to. Linked by id (<code>channelId</code>).</li><li><strong>Event</strong> (<code>marketingEvent</code>, optional) — a dated marketing event the campaign can line up with. May be <code>null</code>. Linked by id (<code>marketingEventId</code>).</li></ul><p>The campaign also carries its own <code>subject</code> (the email subject line) and a <code>status</code> (<code>0</code> inactive / <code>1</code> active).</p><p><strong>Resolved objects.</strong> The <a href="/api/graphql-api/admin/marketing/communications/campaigns-detail.html">detail</a> query resolves the <code>channel</code>, <code>customerGroup</code>, and <code>marketingTemplate</code> objects — sub-select the fields you need from each. The campaign&#39;s event is <strong>REST-only</strong>: read <code>marketingEvent</code> (object or <code>null</code>) via the <a href="/api/rest-api/admin/marketing/communications/campaigns-detail.html">REST detail</a>; it is not field-selectable over GraphQL. On <a href="/api/graphql-api/admin/marketing/communications/campaigns-list.html">list</a> rows the objects are <code>null</code>.</p><p><strong>Sending.</strong> <a href="/api/graphql-api/admin/marketing/communications/campaigns-send.html">Send</a> queues the template to every subscribed member of the campaign&#39;s customer group immediately, skipping any event-date gate. Only an active campaign (<code>status</code> = <code>1</code>) can be sent — sending an inactive one returns a <code>422</code> error.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/marketing/communications/campaigns-list.html">List</a></td><td><code>adminMarketingCampaigns</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/campaigns-detail.html">Detail</a></td><td><code>adminMarketingCampaign</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/campaigns-create.html">Create</a></td><td><code>createAdminMarketingCampaign</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/campaigns-update.html">Update</a></td><td><code>updateAdminMarketingCampaign</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/campaigns-delete.html">Delete</a></td><td><code>deleteAdminMarketingCampaign</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/campaigns-send.html">Send</a></td><td><code>createAdminMarketingCampaignSend</code> mutation</td></tr></tbody></table><p>The <code>channel</code>, <code>customerGroup</code>, and <code>marketingTemplate</code> objects resolve only on the <strong>detail</strong> query — they are <code>null</code> on list rows. The campaign&#39;s event is REST-only. Create / update mutation payloads do not resolve the objects — re-query the detail.</p><p><strong>Relations.</strong> Campaigns draw on <strong>Email Templates</strong> (the body), <strong>Events</strong> (the optional date anchor), and <strong>Newsletter Subscribers</strong> (the audience — a send reaches the subscribed members of the chosen customer group).</p><p>All Campaigns operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',13)]))}const h=a(o,[["render",r]]);export{l as __pageData,h as default};
